1	package netdiag
2	
3	import (
4		"strings"
5		"testing"
6		"time"
7	
8		tea "charm.land/bubbletea/v2"
9	
10		"github.com/anthnel/devdesk/internal/command"
11		"github.com/anthnel/devdesk/internal/netcheck"
12		"github.com/anthnel/devdesk/internal/ui/components"
13		"github.com/anthnel/devdesk/internal/ui/keymap"
14		"github.com/anthnel/devdesk/internal/ui/testutil"
15	)
16	
17	// ── Construction ─────────────────────────────────────────────────────────────
18	
19	// TestTheFormAsksThreeQuestions is the shape of §netcheck: the seven checkboxes
20	// asked the user to select tools, which the pipeline derives.
21	func TestTheFormAsksThreeQuestions(t *testing.T) {
22		m := New(testConfig())
23	
24		if m.state != StateInput {
25			t.Errorf("state = %v, want StateInput", m.state)
26		}
27		if fieldCount != 4 {
28			t.Errorf("the form has %d fields, want 4 — target, port, resolver, button", fieldCount)
29		}
30		if m.focusedField != fieldTarget {
31			t.Errorf("focus starts on %d, want the target field", m.focusedField)
32		}
33	}
34	
35	// TestTheResolverDefaultsToTheSystemOne — the old default read the first
36	// nameserver out of /etc/resolv.conf, which does not exist on Windows, so the
37	// field was silently empty on the platform this is developed on. Empty now
38	// means the system resolver, and says so.
39	func TestTheResolverDefaultsToTheSystemOne(t *testing.T) {
40		m := New(testConfig())
41	
42		if got := m.dnsServerInput.Value(); got != "" {
43			t.Errorf("resolver field starts as %q, want empty", got)
44		}
45		if !strings.Contains(m.dnsServerInput.Placeholder, "system") {
46			t.Errorf("placeholder %q does not say what empty means", m.dnsServerInput.Placeholder)
47		}
48	}
49	
50	// TestNewWithTargetPrefillsTheForm covers status's H (§3.66): the form is
51	// filled from an already-known target rather than left for the user to type,
52	// and it stays a form — NewWithTarget does not itself start the run.
53	func TestNewWithTargetPrefillsTheForm(t *testing.T) {
54		m := NewWithTarget(testConfig(), netcheck.Target{Host: "example.com", Port: 8443, Resolver: "1.1.1.1"})
55	
56		if got := m.targetInput.Value(); got != "example.com" {
57			t.Errorf("target = %q, want %q", got, "example.com")
58		}
59		if got := m.portInput.Value(); got != "8443" {
60			t.Errorf("port = %q, want %q", got, "8443")
61		}
62		if got := m.dnsServerInput.Value(); got != "1.1.1.1" {
63			t.Errorf("resolver = %q, want %q", got, "1.1.1.1")
64		}
65		if m.state != StateInput {
66			t.Errorf("state = %v, want StateInput — NewWithTarget must not itself start the run", m.state)
67		}
68	}
69	
70	func TestInitLoadsBothSubTabs(t *testing.T) {
71		if New(testConfig()).Init() == nil {
72			t.Fatal("Init returned no command")
73		}
74	}
75	
76	// ── Tabs ─────────────────────────────────────────────────────────────────────
77	
78	func TestTabCyclesThroughEveryTab(t *testing.T) {
79		m := newTestModel(t)
80		for _, want := range []int{tabPorts, tabInterfaces, tabForward, tabDiagnostics} {
81			m = feed(t, m, testutil.Key("tab"))
82			if m.activeTab != want {
83				t.Fatalf("activeTab = %d, want %d", m.activeTab, want)
84			}
85		}
86		for _, want := range []int{tabForward, tabInterfaces, tabPorts, tabDiagnostics} {
87			m = feed(t, m, testutil.Key("shift+tab"))
88			if m.activeTab != want {
89				t.Fatalf("activeTab = %d, want %d", m.activeTab, want)
90			}
91		}
92	}
93	
94	// The cycle is stated over tabCount rather than over a list written out twice,
95	// so a fifth tab cannot be added to the bar and forgotten in the arithmetic.
96	func TestEveryTabIsReachableByTabAlone(t *testing.T) {
97		m := newTestModel(t)
98		seen := map[int]bool{m.activeTab: true}
99		for i := 0; i < tabCount; i++ {
100			m = feed(t, m, testutil.Key("tab"))
101			seen[m.activeTab] = true
102		}
103		if len(seen) != tabCount {
104			t.Errorf("tab reached %d of the %d tabs", len(seen), tabCount)
