package netdiag

import (
	"errors"
	"fmt"
	"net/netip"
	"reflect"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/nettrace"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-328 step 4: the Path tab's own model. No test runs the launch Cmd
// (it would start the producer); step 3 covers the producer.

func newPM(t *testing.T) (*PathModel, *fakeEngine) {
	t.Helper()
	f := &fakeEngine{}
	pm := newPathModel(f.engine())
	pm.resize(120, 30)
	return pm, f
}

// pmFeed delivers msgs in order and returns the model and the last Cmd.
func pmFeed(t *testing.T, pm *PathModel, msgs ...tea.Msg) (*PathModel, tea.Cmd) {
	t.Helper()
	var cmd tea.Cmd
	for _, msg := range msgs {
		pm, cmd = pm.update(msg)
		if pm == nil {
			t.Fatal("update returned a nil model")
		}
	}
	return pm, cmd
}

// launched types target and presses enter.
func launched(t *testing.T, pm *PathModel, target string) (*PathModel, tea.Cmd) {
	t.Helper()
	pm, _ = pmFeed(t, pm, testutil.Type(target)...)
	return pmFeed(t, pm, testutil.Key("enter"))
}

func pmHopTTLs(pm *PathModel) []int {
	var out []int
	for _, h := range pm.table.Items() {
		out = append(out, h.TTL)
	}
	return out
}

func pmFooter(pm *PathModel, width int) string {
	return ansi.Strip(pm.footer.View(width, pm.statusLine()))
}

func headerValue(pm *PathModel, key string) (string, bool) {
	for _, h := range pm.headerInfo() {
		if h.Key == key {
			return h.Value, true
		}
	}
	return "", false
}

func hopOf(ttl int, kind nettrace.HopKind) nettrace.Hop {
	return nettrace.Hop{TTL: ttl, Kind: kind, Addr: netip.MustParseAddr("10.0.0.1")}
}

// Criterion 1 and 6: field and launch key visible, the body is a table even empty.

	case netcheck.OK:
		return theme.StatusOKStyle
	default:
		return theme.DimStyle
	}
}

// GetFooterHeight implements FooterView — tab bar + empty + info + ports filter bar when visible (Rule 124)
func (m *Model) GetFooterHeight() int {
	if m.activeTab == tabPorts {
		return 3 + m.portsModel.table.FilterBar().ExtraHeight()
	}
	if m.activeTab == tabDiagnostics {
		return 3 + m.filterBar.ExtraHeight()
	}
	if m.activeTab == tabInterfaces {
		return 3 + m.interfacesModel.table.FilterBar().ExtraHeight()
	}
	if m.activeTab == tabForward {
		return 3 + m.forwardModel.table.FilterBar().ExtraHeight()
	}
	return 3
}

// RenderFooter implements FooterView
func (m *Model) RenderFooter(width int) string {
	var parts []string

	// The active tab's filter bar renders above the tab bar when visible.
	switch {
	case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
		parts = append(parts, m.portsModel.table.FilterBar().View())
	case m.activeTab == tabDiagnostics && m.filterBar.IsVisible():
		parts = append(parts, m.filterBar.View())
	case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
		parts = append(parts, m.interfacesModel.table.FilterBar().View())
	case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
		parts = append(parts, m.forwardModel.table.FilterBar().View())
	}

	tabs := theme.RenderTabs([]theme.TabItem{
		{Label: "Diagnostics"},
		{Label: "Ports"},
		{Label: "Interfaces"},
		{Label: "Forward"},
	}, m.activeTab)
	tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)

	// The message belongs to the tab that raised it: each sub-model keeps its
	// own, so switching away does not carry one tab's notice onto another.
	footer, status := m.activeFooter()
	parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
	return strings.Join(parts, "\n")
}

// activeFooter resolves the message line of whichever tab is on screen, and the
// status that tab derives on every frame.
func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
	switch m.activeTab {
	case tabPorts:
		return &m.portsModel.footer, m.portsModel.statusLine()
	case tabInterfaces:
		return &m.interfacesModel.footer, m.interfacesModel.statusLine()
	case tabForward:
		return &m.forwardModel.footer, m.forwardModel.status()
	}
	return &m.footer, m.statusLine()
}

// statusLine is what the diagnostics tab derives on every frame: a progress
// label while the pipeline walks, and nothing once it has an answer. It is a
// status rather than a footer message because it is a state, not an event —
// a message expires after three seconds and a run outlives that (Rule 128).
func (m *Model) statusLine() components.Status {
	if m.state == StateRunning {
		return components.Status{Text: m.progressLabel(), Activity: true}
	}
	return components.Status{}
}

